#!/usr/bin/env bash
# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
set -euo pipefail

usage() {
  cat <<'EOF'
run_test.sh — health_risk: keygen -> encrypt -> server -> decrypt, then compare to the faithful twin.
Usage: ./run_test.sh [--cpu | --sim | --sim-full | -h]
  (no flag)   dispatch to the Niobium Fog (default; records hollow, needs an API key)
  --cpu       plain-OpenFHE local validation
  --sim       hollow record -> local fhetch_sim replay -> twin compare (a Fog rehearsal)
  --sim-full  real-math record -> replay + ring-level ciphertext-identity check vs OpenFHE
              (compare --sim and --sim-full to surface any hollow-recording divergence)
Env: FOG_TARGET (default FOG; FUNC_SIM = hardware-free simulator)
     RINGCHK    (set to --no-ring-dim-check only for a deliberately small ring)
     RING_DIM   (default 65536; smaller rings are for quick local runs only)
     RECORD     which test patient to score (default 0 = CVrisk's published test case)
     NREC       validation-sweep size (default 1). Patients after the first replay
                the trace recorded for the first one.
EOF
}

MODE="fog"; FLAG=""; SIMFULL=0
case "${1:-}" in
  --cpu) MODE="cpu"; FLAG="--cpu";;
  --sim) MODE="sim"; FLAG="--sim";;
  --sim-full) MODE="sim"; FLAG="--sim"; SIMFULL=1;;
  "")    MODE="fog";;
  -h|--help) usage; exit 0;;
  *) usage; exit 2;;
esac

FOG_TARGET="${FOG_TARGET:-FOG}"   # the real Niobium Fog; FUNC_SIM is the explicit hardware-free opt-in
RINGCHK="${RINGCHK:-}"
RING_DIM="${RING_DIM:-65536}"
HOLLOW_FLAG=""
case "$MODE" in
  fog) HOLLOW_FLAG="--hollow"; RINGCHK=""; RING_DIM=65536;;   # the Fog runs exactly 2^16
  sim) [ "$SIMFULL" = 1 ] || HOLLOW_FLAG="--hollow";;
esac
# The server does not know --sim; it only distinguishes --cpu from a recorded run.
[ "$FLAG" = "--sim" ] && FLAG=""
RECORD="${RECORD:-0}"
NREC="${NREC:-1}"

ROOT="$(cd "$(dirname "$0")" && pwd)"
REPO="$(cd "$ROOT/../.." && pwd)"
BUILD="$REPO/build/examples"
export NBCC_FHETCH_SIM="${NBCC_FHETCH_SIM:-$REPO/build/vendor/niobium-fhetch/fhetch_sim}"
[ -x "$BUILD/health_risk_server" ] || make -C "$REPO" build-release
MEASURE=(python3 "$ROOT/tools/measure.py")

RUN="$ROOT/run_${MODE}"; [ "$SIMFULL" = 1 ] && RUN="$ROOT/run_sim-full"
CLIENT="$RUN/client_home"; SERVER="$RUN/server_home"
# Fresh homes, which also clears the trace cache (it lives in the server home).
rm -rf "$RUN"; mkdir -p "$CLIENT" "$SERVER"
PROFILE="$RUN/profile.txt"; SIZES="$RUN/sizes.txt"

# 1. keygen writes ALL keys into the client home
"${MEASURE[@]}" "$PROFILE" keygen -- "$BUILD/health_risk_keygen" "$CLIENT" "$RING_DIM" >/dev/null

# 2. provision the server home: context, public + eval keys, model. NO secret key, NO inputs.
cp "$CLIENT/cc.bin" "$CLIENT/pk.bin" "$CLIENT/mk.bin" "$CLIENT/rk.bin" "$SERVER/"
cp "$ROOT/data/model.txt" "$SERVER/"
[ ! -f "$SERVER/sk.bin" ] || { echo "[FATAL] secret key in server home"; exit 1; }
for f in pk.bin mk.bin rk.bin; do echo "setup:$f $(wc -c < "$SERVER/$f")" >> "$SIZES"; done

# 3. negative test: the server must refuse to start with a secret key in its home
cp "$CLIENT/sk.bin" "$SERVER/sk.bin"
if (cd "$SERVER" && "$BUILD/health_risk_server" . $FLAG $RINGCHK >/dev/null 2>&1); then
  echo "[FATAL] server started with a secret key present"; exit 1
fi
rm -f "$SERVER/sk.bin"; echo "negative test: server refused a planted secret key"

# 4. Fog mode: preflight for an API key; with a key present, the dispatch below is mandatory
if [ "$MODE" = "fog" ] && [ ! -f "$HOME/.fog/credentials" ] && [ -z "${FOG_API_TOKEN:-}" ]; then
  echo "No Fog API key found — not dispatching."
  echo "  Sign in:  fog login        Sign up:  https://console.niobium.co/request-account"
  echo "  Account-free local validation:  ./run_test.sh --sim"
  exit 0
fi

# 5. encrypt -> server -> decrypt, one patient at a time (bounds enforcement lives in
#    health_risk_encrypt). The trace recorded for the first patient is replayed for the rest.
: > "$RUN/decrypted.txt"
for ((i=RECORD; i<RECORD+NREC; i++)); do
  # test_patients.csv: sex,age,bmi,sbp,bp_treated,smoker,diabetic,...
  read -r SEX AGE BMI SBP TRT SMK DIA < <(awk -F, -v n=$((i + 2)) \
    'NR==n { print ($1=="male" ? "m" : "f"), $2, $3, $4, $5, $6, $7 }' "$ROOT/data/test_patients.csv")
  "${MEASURE[@]}" "$PROFILE" encrypt -- \
    "$BUILD/health_risk_encrypt" "$CLIENT" "$CLIENT/ct_x_$i.bin" "$SEX" "$AGE" "$BMI" "$SBP" "$TRT" "$SMK" "$DIA"
  cp "$CLIENT/ct_x_$i.bin" "$SERVER/ct_x.bin"          # only ciphertext crosses
  if [ "$MODE" = "fog" ]; then
    # THE DEFAULT PATH: the server runs under `fog submit`. The ring-dim guard stays on
    # (RINGCHK is never forwarded here), so a non-2^16 ring cannot reach the Fog.
    (cd "$SERVER" && "${MEASURE[@]}" "$PROFILE" server -- \
      fog submit "$BUILD/health_risk_server" . $HOLLOW_FLAG --target="$FOG_TARGET")
  else
    # --sim passes --hollow (server records hollow, skips its ring-level check);
    # --sim-full omits it (real record, so the server's ring-level check runs).
    (cd "$SERVER" && "${MEASURE[@]}" "$PROFILE" server -- \
      "$BUILD/health_risk_server" . $FLAG $HOLLOW_FLAG $RINGCHK) > "$RUN/server_$i.log" 2>&1 \
      || { echo "[FAIL] server, patient $i — see $RUN/server_$i.log"; tail -5 "$RUN/server_$i.log"; exit 1; }
    grep -E "^\[server\]" "$RUN/server_$i.log" | sed "s/^/  patient $i /"
  fi
  cp "$SERVER/ct_result.bin" "$CLIENT/ct_result_$i.bin"
  "${MEASURE[@]}" "$PROFILE" decrypt -- \
    "$BUILD/health_risk_decrypt" "$CLIENT" "$CLIENT/ct_result_$i.bin" >> "$RUN/decrypted.txt"
done
echo "per-query:ct_x.bin $(wc -c < "$SERVER/ct_x.bin")" >> "$SIZES"
echo "per-query:ct_result.bin $(wc -c < "$SERVER/ct_result.bin")" >> "$SIZES"

# 6. report: the answer, then encryption fidelity (the exit code), then the profile
python3 "$ROOT/tools/report.py" "$RUN" "$RECORD" "$NREC" "$MODE$([ "$SIMFULL" = 1 ] && echo -full)"
